package top.frostor.carpet.playerladder;

import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.builder.ArgumentBuilder;
import com.mojang.brigadier.builder.LiteralArgumentBuilder;
import com.mojang.brigadier.tree.CommandNode;
import com.mojang.brigadier.tree.LiteralCommandNode;
import net.minecraft.commands.CommandBuildContext;
import net.minecraft.commands.CommandSourceStack;
import top.frostor.carpet.FrostorSettings;

import java.util.function.Predicate;

/**
 * Registers the command tree generated by Carpet's settings manager under {@code /playerladder}.
 */
public final class PlayerLadderCommand {
    private PlayerLadderCommand() {
    }

    public static void register(
            CommandDispatcher<CommandSourceStack> dispatcher,
            CommandBuildContext buildContext
    ) {
        PlayerLadderSettings.initialize();

        CommandDispatcher<CommandSourceStack> generatedDispatcher = new CommandDispatcher<>();
        PlayerLadderSettings.MANAGER.registerCommand(generatedDispatcher, buildContext);
        LiteralCommandNode<CommandSourceStack> generatedRoot = (LiteralCommandNode<CommandSourceStack>)
                generatedDispatcher.getRoot().getChild("playerladder");
        if(generatedRoot == null) throw new IllegalStateException("Carpet did not register /playerladder");

        dispatcher.register(copyRoot(
                generatedRoot,
                source -> FrostorSettings.playerLadder
        ));
    }

    static LiteralArgumentBuilder<CommandSourceStack> copyRoot(
            LiteralCommandNode<CommandSourceStack> generatedRoot,
            Predicate<CommandSourceStack> additionalRequirement
    ) {
        Predicate<CommandSourceStack> carpetRequirement = generatedRoot.getRequirement();
        LiteralArgumentBuilder<CommandSourceStack> root = generatedRoot.createBuilder();
        root.requires(source -> carpetRequirement.test(source) && additionalRequirement.test(source));
        CommandNode<CommandSourceStack> listCommand = generatedRoot.getChild("list");
        if(listCommand != null && listCommand.getCommand() != null)
            root.executes(listCommand.getCommand());
        for(CommandNode<CommandSourceStack> child : generatedRoot.getChildren()) {
            if(child == listCommand) continue;
            root.then(copyNode(child));
        }
        return root;
    }

    private static ArgumentBuilder<CommandSourceStack, ?> copyNode(CommandNode<CommandSourceStack> node) {
        ArgumentBuilder<CommandSourceStack, ?> builder = node.createBuilder();
        for(CommandNode<CommandSourceStack> child : node.getChildren())
            builder.then(copyNode(child));
        return builder;
    }
}
